<aside class="h-fit rounded-2xl border border-slate-200 bg-white p-6 shadow-sm"><h2 class="text-lg font-black text-[#10203d]">Publishing</h2><p class="mt-2 text-sm leading-6 text-slate-500">Drafts remain private. Scheduled items publish when the scheduler runs. Published items become available immediately.</p><label class="mt-5 grid gap-2"><span class="text-xs font-black">Status</span><select name="status" class="rounded-lg border-slate-300">@foreach(['draft','scheduled','published'] as $status)<option value="{{ $status }}" @selected(old('status',$item->status ?: 'draft')===$status)>{{ ucfirst($status) }}</option>@endforeach</select></label><label class="mt-4 grid gap-2"><span class="text-xs font-black">Schedule publication</span><input type="datetime-local" name="scheduled_for" value="{{ old('scheduled_for',$item->scheduled_for?->format('Y-m-d\TH:i')) }}" class="rounded-lg border-slate-300"></label><button class="mt-6 w-full rounded-lg bg-teal-700 px-5 py-3 text-sm font-black text-white">Save {{ $label }}</button>@if($item->published_at)<p class="mt-4 text-xs font-semibold text-emerald-700">Published {{ $item->published_at->diffForHumans() }}</p>@endif</aside>
